using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Qms.Domain.Complaints;
namespace Qms.Infrastructure.Persistence.Configurations;
public sealed class ComplaintResponseConfiguration:IEntityTypeConfiguration<ComplaintResponse>{public void Configure(EntityTypeBuilder<ComplaintResponse>b){b.ToTable("response_version","complaint");b.HasKey(x=>x.Id);b.Property(x=>x.ResponseType).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Content).HasMaxLength(10000).IsRequired();b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.PreparedBy).HasMaxLength(200).IsRequired();b.Property(x=>x.ApprovedBy).HasMaxLength(200);b.HasIndex(x=>new{x.ComplaintId,x.ResponseType,x.VersionNumber}).IsUnique();b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.PreparedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.ApprovedByUserId).OnDelete(DeleteBehavior.Restrict);}}

